func zigZagArrays(n int, l int, r int) int {
	const mod = int64(1e9 + 7)
	m := r - l + 1
	up := make([]int64, m)
	down := make([]int64, m)
	for i := range up {
		up[i], down[i] = 1, 1
	}
	for k := 1; k < n; k++ {
		pre := make([]int64, m+1)
		suf := make([]int64, m+1)
		for i := 0; i < m; i++ {
			pre[i+1] = (pre[i] + down[i]) % mod
		}
		for i := m - 1; i >= 0; i-- {
			suf[i] = (suf[i+1] + up[i]) % mod
		}
		for i := 0; i < m; i++ {
			up[i] = pre[i]
			down[i] = suf[i+1]
		}
	}
	var ans int64
	for i := 0; i < m; i++ {
		ans = (ans + up[i] + down[i]) % mod
	}
	return int(ans)
}

int zigZagArrays(int n, int l, int r) {
    int mod = 1e9 + 7;
    int m = r - l + 1;
    long long up[m], down[m];
    for (int i = 0; i < m; ++i) {
        up[i] = down[i] = 1;
    }
    for (int k = 1; k < n; ++k) {
        long long pre[m + 1], suf[m + 1];
        memset(pre, 0, sizeof(pre));
        memset(suf, 0, sizeof(suf));
        for (int i = 0; i < m; ++i) {
            pre[i + 1] = (pre[i] + down[i]) % mod;
        }
        for (int i = m - 1; i >= 0; --i) {
            suf[i] = (suf[i + 1] + up[i]) % mod;
        }
        for (int i = 0; i < m; ++i) {
            up[i] = pre[i];
            down[i] = suf[i + 1];
        }
    }
    long long ans = 0;
    for (int i = 0; i < m; ++i) {
        ans = (ans + up[i] + down[i]) % mod;
    }
    return ans;
}
